)
[ -z "$(find "$source" ! -type f ! -type d -print)" ] || fail 'Unsupported source entry (including symlink)'
actual=$(cd "$source" && find . -type f -print | LC_ALL=C sort)
expected=$(printf '%s\n' "$paths" | while IFS= read -r path; do printf './%s\n' "$path"; done)
[ "$actual" = "$expected" ] || fail 'Source file inventory mismatch'
verify() { printf '%s\n' "$checksums" | (cd "$1" && checksum -c -) >/dev/null || fail 'Skill digest mismatch'; }
verify "$source"
# No destination path component (leaf or ancestor, up to $base) may be a
# symlink. Reused at preflight and again immediately before each write
# below: a same-UID attacker who plants a link after preflight is still
# caught at the latest possible instant before that path is touched. This
# narrows, but cannot fully close on a portable POSIX shell, the window
# between the final recheck and the write; see docs/AGENT-SKILLS.md.
assert_no_link() {
    current=$1
    while [ "$current" != "$base" ]; do
        [ ! -L "$current" ] || fail "Symlink destination: $current"
        current=${current%/*}
        [ -n "$current" ] || current=/
    done
}
# Preflight every destination (including receipt) before any write.
printf '%s\n' "$paths" '.omj-agent-skills-manifest.json' | while IFS= read -r path; do
    assert_no_link "$target/$path"
    [ ! -e "$target/$path" ] || [ -f "$target/$path" ] || fail "Not a file: $target/$path"
    [ "$path" = '.omj-agent-skills-manifest.json' ] || [ ! -e "$target/$path" ] || cmp -s "$source/$path" "$target/$path" || fail "Unowned or modified collision: $target/$path"
done
# Each write is: recheck the exact destination, create its content under an
# exclusive (O_CREAT|O_EXCL via shell noclobber) temp name in the same
# directory, then replace the destination with one atomic rename. rename(2)
# always replaces whatever directory entry is there; it never follows a
# symlink planted at the destination in the gap after the recheck.
write_atomic() {
    src=$1 dst=$2
    assert_no_link "$dst"
    tmp="$dst.$$.tmp"
    (set -C; cat "$src" > "$tmp") 2>/dev/null || fail "Temp write collision: $tmp"
    mv -f "$tmp" "$dst"
}
printf '%s\n' "$paths" | while IFS= read -r path; do
    assert_no_link "$target/${path%/*}"
    mkdir -p "$target/${path%/*}"
    write_atomic "$source/$path" "$target/$path"
done
verify "$target"
receipt_tmp="$target/.omj-agent-skills-manifest.json.$$.tmp"
